import { contentService } from './services/content-service.js';
import { searchContent } from './services/search-service.js';
const app=document.getElementById('app');
const DATA=await contentService.getAll();
const A='assets/images/';
const guideAssets={
  nn:{connect:'nn-connect.jpg',shake:'nn-shake-wake.jpg',standby:'nn-standby.jpg',placement1:'nn-emg-placement-1.jpg',placement2:'nn-emg-placement-2.jpg',electrodes:'nn-electrode-options.jpg',band:'nn-band-bezel.jpg',good1:'nn-good-signal-1.jpg',good2:'nn-good-signal-2.jpg',controller:'nn-controller-graph.jpg',graph:'nn-graph-menu.jpg',settings:'nn-graph-settings.jpg',static:'nn-static-scaling.jpg',dynamic:'nn-dynamic-scaling.jpg',profiles:'nn-profiles.jpg',auto:'nn-auto-calibration.jpg',grid:'nn-grid3-connect.jpg',hid:'nn-hid-f9.jpg',charge:'nn-charging-detail.jpg',features:'nn-features-charge.jpg',reset:'nn-reset-repair.jpg',indicators:'nn-indicators-detail.jpg'},
  ns:{overview:'ns-guide-overview.png',dashboard:'ns-guide-dashboard.png',skin:'ns-skin-preparation.jpg',placement1:'ns-emg-placement-1.jpg',placement2:'ns-emg-placement-2.jpg',patch:'ns-patch-alignment.jpg',connections:'ns-guide-connections.png',patient:'ns-guide-new-patient.png',patientOverview:'ns-guide-patient-overview.png',patientSessions:'ns-guide-patient-sessions.png',measurements:'ns-guide-measurements.png',protocols:'ns-guide-protocols.png',create1:'ns-guide-create-protocol-1.png',create2:'ns-guide-create-protocol-2.png',edit:'ns-guide-edit-protocol.png',newSession:'ns-guide-new-session.png',selectProtocol:'ns-guide-select-protocol.png',sessionGraph:'ns-guide-session-graph.png',graphControls:'ns-guide-graph-controls.png',troubleshooting:'ns-guide-troubleshooting.png',dysphagia1:'ns-dysphagia-overview.png',dysphagia2:'ns-dysphagia-use-cases.png'}
};
function e(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function hero(kicker,title,desc,actions=''){return `<section class="hero"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p>${actions?`<div class="hero-actions">${actions}</div>`:''}</section>`}
function bread(items){return `<div class="breadcrumbs">${items.map((x,i)=>i===items.length-1?e(x[0]):`<a href="${x[1]}">${e(x[0])}</a> <span>›</span> `).join('')}</div>`}
function pageTitle(items,title,desc=''){return `<div class="page-title">${bread(items)}<h1>${title}</h1>${desc?`<p class="lede">${desc}</p>`:''}</div>`}
function card(title,desc,href,icon='→'){return `<a class="card" href="${href}"><h3>${title}</h3><p>${desc}</p><span class="arrow">${icon}</span></a>`}
function img(src,alt){return `<img class="guide-image" src="${A+src}" alt="${e(alt)}" data-zoom>`}
function steps(items){return `<div class="step-list">${items.map((x,i)=>`<article class="step"><div class="step-num">${i+1}</div><div><h3>${x[0]}</h3><p>${x[1]}</p>${x[2]?img(x[2],x[0]):''}</div></article>`).join('')}</div>`}
function tabs(items){return `<nav class="tabs">${items.map(x=>`<a href="${x[1]}">${x[0]}</a>`).join('')}</nav>`}
function osSwitch(current,windowsHref,iosHref){const isWindows=current==='windows';const target=isWindows?'iOS':'Windows';const href=isWindows?iosHref:windowsHref;return `<a class="os-switch" href="${href}" aria-label="Switch to ${target} version"><strong>${target} version</strong><small>Click here to switch to ${target} version</small></a>`}
function mascot(which,text){const src=which==='nodi'?'nodi-neuronode.png':'nero-transparent.png';return `<aside class="mascot-tip"><img src="${A+src}" alt="${which==='nodi'?'Nodi':'Nero'} mascot"><div><strong>${which==='nodi'?'Nodi':'Nero'} tip</strong><div class="muted">${text}</div></div></aside>`}

function resourceById(id){return DATA.resources.find(r=>r.id===id)}
function resourceCard(r){if(!r)return '';const external=r.href&&r.href.startsWith('http');if(!r.href)return `<div class="card resource-card resource-pending"><span class="badge">${e(r.type)}</span><span><h3>${e(r.title)}</h3><p>${e(r.product)} • ${e(r.desc)}</p><span class="muted">Link pending</span></span></div>`;return `<a class="card resource-card" href="${r.href}" ${external?'target="_blank" rel="noopener"':''}><span class="badge">${e(r.type)}</span><span><h3>${e(r.title)}</h3><p>${e(r.product)} • ${e(r.desc)}</p><span class="arrow">${external?'Open official resource ↗':'View resource →'}</span></span></a>`}
function relatedResources(ids,title='Related resources',limit=6){const rows=ids.map(resourceById).filter(Boolean).slice(0,limit);if(!rows.length)return '';return `<section class="section contextual-resources"><div class="section-head"><div><h2>${e(title)}</h2><p>Official resources relevant to this page.</p></div><a class="btn ghost" href="#/resources">View full Resource Library →</a></div><div class="grid ${rows.length>=3?'three':'two'}">${rows.map(resourceCard).join('')}</div></section>`}
function home(){return `<div class="page">${hero('CONTROL BIONICS','Support & Learning Hub','Self-service setup, troubleshooting, training and resources for Control Bionics AAC systems and NeuroStrip.',`<a class="btn primary" href="#/aac">Explore AAC →</a><a class="btn secondary" href="#/neurostrip">Explore NeuroStrip →</a>`)}<div class="quick-search"><input data-search-trigger placeholder="Search for a device, problem or guide…"><button class="btn primary" data-open-search>Search</button></div><section class="section"><div class="section-head"><div><h2>What do you need help with?</h2><p>Choose the product family first, then follow a task-based guide.</p></div></div><div class="grid two">${card('AAC Support','UNO Touch, EyeGaze Duo, NeuroNode, NeuroNode Duo, NeuroNode Trilogy and mounting.','#/aac','Explore AAC →')}${card('NeuroStrip','Get started, run sessions, troubleshoot and learn surface EMG.','#/neurostrip','Explore NeuroStrip →')}</div></section><section class="section"><div class="section-head"><h2>Popular</h2></div><div class="grid four">${card('Getting Started','New device? Start with the shortest setup pathway.','#/aac')}${card('Troubleshooting & FAQs','Find answers by symptom rather than by manual section.','#/faqs')}${card('EMG Academy','Future home for 15 short NeuroStrip training lessons.','#/academy')}${card('Resources','Manuals, quick starts, software and trusted external links.','#/resources')}</div></section><section class="section">${mascot('nero','Choose AAC or NeuroStrip first. The site then shows only the support content relevant to that product family.')}</section></div>`}
function aac(){return `<div class="page">${pageTitle([['Home','#/'],['AAC']], 'AAC Support','Choose your device. Mounting is listed separately because it supports multiple systems rather than being an AAC device itself.')}<div class="grid three">${DATA.products.map(p=>`<a class="card product-card" href="${p.route}"><img src="${p.img}" alt="${e(p.name)}"><h3>${p.name}</h3><p>${p.desc}</p><span class="arrow">Get support →</span></a>`).join('')}</div><section class="section"><div class="section-head"><h2>Common AAC questions</h2><a class="btn ghost" href="#/faqs">View all FAQs →</a></div><div class="grid three">${DATA.faq.filter(x=>x[0]!=='NeuroStrip').slice(0,6).map(x=>card(x[2],x[3],x[4])).join('')}</div></section></div>`}
function uno(){return `<div class="page page-wide">${pageTitle([['Home','#/'],['AAC','#/aac'],['UNO Touch']], 'UNO Touch','Choose Windows or iOS. The guide layout is based on the approved Neuroverse page-design PDF rather than the older trial-card drafts.')}${tabs([['Windows','#/aac/uno-touch/windows'],['iOS','#/aac/uno-touch/ios'],['Help & FAQs','#/aac/uno-touch/help']])}<div class="grid three">${card('Windows setup','Getting Started and the equipment checklist shown together in one landscape view.','#/aac/uno-touch/windows')}${card('iOS setup','The same compact layout with Grid for iPad in the second step.','#/aac/uno-touch/ios')}${card('Help & FAQs','UNO Touch support questions.','#/aac/uno-touch/help')}</div>${relatedResources(['resource-uno-touch-au','resource-grid3-support','resource-grid-ipad-support'],'UNO Touch resources')}</div>`}
function unoSetup(os){const windows=os==='windows';const secondTitle=windows?'Check':'Open';const secondText=windows?'Grid 3 will open up':'Find desired app to open (e.g. Grid for iPad)';const secondImg=windows?'uno-grid3.png':'uno-grid-ipad.png';const P='pdf-source/';return `<div class="page page-wide guide-page os-page">${osSwitch(os,'#/aac/uno-touch/windows','#/aac/uno-touch/ios')}${pageTitle([['Home','#/'],['AAC','#/aac'],['UNO Touch','#/aac/uno-touch'],[windows?'Windows':'iOS']],`UNO Touch — ${windows?'Windows':'iOS'} Getting Started`,'')}${tabs([[windows?'✓ Windows':'Windows','#/aac/uno-touch/windows'],[!windows?'✓ iOS':'iOS','#/aac/uno-touch/ios'],['Help','#/aac/uno-touch/help']])}<div class="uno-landscape"><section class="guide-panel guide-panel-main"><div class="panel-title purple">Getting Started</div><div class="compact-steps">${[
['Turn on UNO Touch Device','Press and hold the power button until the screen lights up.','uno-device.png'],
[secondTitle,secondText,secondImg],
['Set up','Turn on Bluetooth speaker by pressing the Play/Pause button.','uno-speaker.png'],
['Get Started!','Now you can use your UNO Touch device.','uno-letsgo.png'],
['Need to know','Repeat step 1 to turn off the device and press and hold Play/Pause button on speaker.','uno-off.png']
].map((x,i)=>`<article class="compact-step"><span class="step-dot">${i+1}</span><div class="step-label">${x[0]}</div><img src="${A+P+x[2]}" alt="${e(x[0])}" data-zoom><p>${e(x[1])}</p></article>`).join('')}</div></section><aside class="guide-panel checklist-panel"><div class="panel-title purple">Checklist</div><div class="checklist-list">${[
['UNO Touch Device','uno-check-device.png'],['Device Charger','uno-charger.png'],['Bluetooth Speaker','uno-check-speaker.png'],['Charger Cord & Wall Plug','uno-cord-plug.png'],['Shoulder Strap','uno-strap.png'],['Optional Keyguard','uno-keyguard.png']
].map(x=>`<div class="check-item"><img src="${A+P+x[1]}" alt=""><strong>${x[0]}</strong></div>`).join('')}</div></aside></div></div>`}
function faqList(filter){let arr=DATA.faq.filter(x=>!filter||x[0]===filter);return `<div>${[...new Set(arr.map(x=>x[1]))].map(cat=>`<div class="faq-group"><h3>${cat}</h3>${arr.filter(x=>x[1]===cat).map(x=>`<details class="faq"><summary>${e(x[2])}</summary><p>${e(x[3])} <a href="${x[4]}">Open related guide →</a></p></details>`).join('')}</div>`).join('')}</div>`}
function neuroNode(){return `<div class="page">${pageTitle([['Home','#/'],['AAC','#/aac'],['NeuroNode']], 'NeuroNode','Start with connection and placement. Advanced Controller App settings remain available without overwhelming new users.')}${tabs([['Get Started','#/aac/neuronode/get-started'],['EMG & Placement','#/aac/neuronode/emg'],['Signal & Calibration','#/aac/neuronode/signal'],['Settings','#/aac/neuronode/settings'],['Grid 3','#/aac/neuronode/grid3'],['Help','#/aac/neuronode/help']])}<div class="grid three">${card('Get Started','What is included, charging, connecting, positioning and a first test switch.','#/aac/neuronode/get-started')}${card('EMG & Placement','Choosing a muscle, electrode options, preparation and good signal.','#/aac/neuronode/emg')}${card('Signal & Calibration','Graph, thresholds, static/dynamic scaling, profiles and Auto Calibration.','#/aac/neuronode/signal')}${card('Switching & Settings','Advanced settings, HID keycode, spatial access, standby and filtering.','#/aac/neuronode/settings')}${card('NeuroNode + Grid 3','Configure Grid 3 switching and change the key assignment.','#/aac/neuronode/grid3')}${card('Troubleshooting & FAQs','Connection, indicators, charging, reset and common problems.','#/aac/neuronode/help')}</div>${relatedResources(['resource-neuronode-user-guide-rev-m','resource-neuronode-firmware-faq','resource-control-bionics-technical-support'],'Official NeuroNode resources')}<section class="section">${mascot('nodi','If a NeuroNode guide is also needed by Duo or Trilogy, link back here instead of duplicating it in three places.')}</section></div>`}
function neuroNodeGetStarted(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['Get Started']], 'Get Started with NeuroNode')}<div class="split"><div>${steps([['Check what is included','Wall charger, charging plate, band, mesh/accessory bag, bezel and NeuroNode.','nn-components.jpg'],['Charge NeuroNode','Place the NeuroNode correctly on the charging plate before setup.','nn-charging-detail.jpg'],['Turn on Bluetooth','On the Windows or iOS device, ensure Bluetooth is on.'],['Open NeuroNode Controller','Launch the Controller App.','nn-controller-graph.jpg'],['Shake to Wake','Shake the NeuroNode so it leaves Standby and can reconnect.','nn-shake-wake.jpg'],['Connect NeuroNode','Select “Connect to NeuroNode” and choose the preferred profile.','nn-connect.jpg'],['Position and test','Place it consistently on the selected access site and make a repeatable activation.','nn-good-signal-1.jpg']])}</div><aside class="sidebar">${mascot('nodi','Consistency matters: place NeuroNode in the same spot and orientation each time when using EMG.')}</aside></div>${relatedResources(['resource-neuronode-user-guide-rev-m','resource-control-bionics-technical-support'],'Reference documents')}</div>`}
function neuroNodeEmg(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['EMG & Placement']], 'EMG Placement & Electrodes','Operational placement guidance from the supplied NeuroNode materials. Clinical selection of a movement or muscle remains the responsibility of the appropriate clinician/team.')}<section class="section"><h2>1. Choose a repeatable activation</h2><p class="lede">Examples in the supplied material include eyebrow/forehead, smile, shoulder shrug, wrist or finger flexion, toe point/heel raise, leg abduction and leg adduction.</p>${img(guideAssets.nn.placement1,'NeuroNode EMG placement examples')}${img(guideAssets.nn.placement2,'Additional NeuroNode EMG placement examples')}</section><section class="section"><h2>2. Choose the electrode setup</h2><div class="grid three">${card('Non-adhesive electrodes','Typically used with the bezel and band on body parts that can be wrapped.','#/aac/neuronode/emg')}${card('Adhesive electrodes','Useful where a strap is difficult to use, and for some alternative placements.','#/aac/neuronode/emg')}${card('Cloth electrodes / leadwire setup','Used in the supplied guidance for facial placements with skin preparation and leadwires.','#/aac/neuronode/emg')}</div>${img(guideAssets.nn.electrodes,'NeuroNode electrode options')}</section><section class="section"><h2>3. Prepare and attach</h2>${img(guideAssets.nn.band,'NeuroNode bezel and band setup')}<div class="callout"><strong>Signal principle:</strong> align the active electrode indicators with the length of the target muscle and keep placement consistent between sessions.</div></section></div>`}
function neuroNodeSignal(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['Signal & Calibration']], 'Signal, Thresholds & Calibration')}<div class="grid two">${card('Controller App overview','Understand the graph, battery indicator and navigation controls.','#/aac/neuronode/signal')}${card('Threshold adjustment','Signal On / Signal Off levels determine when an activation counts as a switch.','#/aac/neuronode/signal')}${card('Static scaling','Manual fixed criteria for switch activation.','#/aac/neuronode/signal')}${card('Dynamic scaling','Criteria adapt over time based on the user’s signal performance.','#/aac/neuronode/signal')}</div><section class="section">${img(guideAssets.nn.controller,'NeuroNode Controller App')}${img(guideAssets.nn.graph,'NeuroNode graph menu')}${img(guideAssets.nn.static,'Static scaling settings')}${img(guideAssets.nn.dynamic,'Dynamic scaling settings')}</section><section class="section"><h2>Profiles & Auto Calibration</h2><p class="lede">Save/manage profiles for repeatable setups. Auto Calibration, where available in the app version, guides the user through a short activation sequence and proposes new Signal On/Off levels.</p>${img(guideAssets.nn.profiles,'NeuroNode profiles')}${img(guideAssets.nn.auto,'NeuroNode Auto Calibration')}</section></div>`}
function neuroNodeSettings(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['Settings']], 'Switching & Advanced Settings')}<div class="grid three">${card('Advanced settings','Language, Auto Baseline, switch tracing, HID sendout, keypress timing and other options.','#/aac/neuronode/settings')}${card('Switch filtering','Adjust filtering behavior where required.','#/aac/neuronode/settings')}${card('Advanced switching','Long Press, Upper Limit and second-switch options for appropriate users.','#/aac/neuronode/settings')}${card('Spatial mode','Use 3D spatial movement rather than EMG where appropriate.','#/aac/neuronode/settings')}${card('HID keycode','Change the keycode sent by NeuroNode, such as F9.','#/aac/neuronode/grid3')}${card('Standby / Shake to Wake','Understand how NeuroNode sleeps and reconnects.','#/aac/neuronode/get-started')}</div><section class="section">${img('nn-advanced-settings.jpg','Advanced settings')}${img('nn-switch-filtering.jpg','Switch filtering')}${img('nn-advanced-switching-1.jpg','Advanced switching')}${img('nn-spatial-settings.jpg','Spatial settings')}</section></div>`}
function neuroNodeGrid(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['Grid 3']], 'Connect NeuroNode to Grid 3','Use Grid 3 switch settings so NeuroNode activations can control scanning or other switch-access functions.')}${steps([['Open Grid 3 settings','Go to Menu → Settings → Access → Switches.'],['Open Connection','Under Switches, choose Connection.'],['Choose Change Key','Select Change Key and activate NeuroNode.'],['Confirm the detected key','Press OK after the activation is detected.'],['Save the connection','Press OK again to keep the change.']])}${img(guideAssets.nn.grid,'Connecting NeuroNode to Grid 3')}<section class="section"><h2>HID keycode example</h2><p class="lede">The supplied guide includes an example of changing HID Keycode Sendout to F9 through Home → Advanced → Advanced Settings.</p>${img(guideAssets.nn.hid,'Change NeuroNode HID keycode to F9')}</section></div>`}
function neuroNodeHelp(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode','#/aac/neuronode'],['Help']], 'NeuroNode Troubleshooting & FAQs','Start with normal customer-safe checks. Keep advanced recovery actions separate so basic support stays simple.')}<div class="grid two">${card('Connection checklist','Bluetooth on → Shake to Wake → Controller App → reconnect.','#/aac/neuronode/get-started')}${card('Bluetooth reset / scrub','Use the App method first; manual reset is a recovery step.','#/aac/neuronode/help')}</div><section class="section"><h2>Signal indicator colours</h2>${img(guideAssets.nn.indicators,'NeuroNode signal indicator colours')}</section><section class="section"><h2>Bluetooth reset</h2>${img(guideAssets.nn.reset,'NeuroNode Bluetooth reset')}<div class="callout warning"><strong>Support boundary:</strong> do not present potentially damaging hardware-short actions as routine customer troubleshooting. Escalate unresolved hardware/firmware states to Control Bionics Support.</div></section><section class="section"><h2>Frequently asked questions</h2>${faqList('NeuroNode')}</section>${relatedResources(['resource-neuronode-firmware-faq','resource-neuronode-user-guide-rev-m','resource-control-bionics-technical-support'],'Troubleshooting resources')}</div>`}
function duo(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode Duo']], 'NeuroNode Duo','Choose the operating system first. NeuroNode placement, signal and switching content is shared with the main NeuroNode guide.')}${tabs([['Windows','#/aac/neuronode-duo/windows'],['iOS','#/aac/neuronode-duo/ios'],['NeuroNode help','#/aac/neuronode'],['Troubleshooting','#/faqs']])}<div class="grid two">${card('Windows','Turn on → Controller App → connect NeuroNode → place NeuroNode → open Grid 3.','#/aac/neuronode-duo/windows')}${card('iOS','Turn on → Controller App → connect NeuroNode → place NeuroNode → open Grid for iPad/AAC software.','#/aac/neuronode-duo/ios')}</div>${relatedResources(['resource-duo-spec-sheet','resource-duo-au-product-sheet','resource-grid3-support'],'NeuroNode Duo resources')}</div>`}
function duoOS(os){const w=os==='windows';return `<div class="page os-page">${osSwitch(os,'#/aac/neuronode-duo/windows','#/aac/neuronode-duo/ios')}${pageTitle([['AAC','#/aac'],['NeuroNode Duo','#/aac/neuronode-duo'],[w?'Windows':'iOS']],`NeuroNode Duo — ${w?'Windows':'iOS'} Setup`)}${steps([['Turn on the device','Press and hold the device power button until the screen lights up.',w?'nn-duo-windows-quick.jpg':'nn-duo-ios-quick.jpg'],['Open NeuroNode Controller','Launch the Controller App.'],['Connect NeuroNode','Shake to Wake and press Connect to NeuroNode.'],['Place NeuroNode','Place NeuroNode at the user’s established access site.'],[w?'Open Grid 3':'Open communication software',w?'Open Grid 3 or another AAC program.':'Open Grid for iPad or another AAC app.'],['Start communicating','Use the shared NeuroNode guides for advanced signal and switching settings.']])}<div class="hero-actions"><a class="btn secondary" href="#/aac/neuronode">Open NeuroNode guide →</a></div>${relatedResources(w?['resource-duo-spec-sheet','resource-grid3-support','resource-surface-support']:['resource-duo-spec-sheet','resource-grid-ipad-support','resource-apple-ipad-accessibility'],'Useful for this version')}</div>`}
function eye(){return `<div class="page">${pageTitle([['AAC','#/aac'],['EyeGaze Duo']], 'EyeGaze Duo','Frontline support should stay focused on setup, USB connections, positioning and calibration. Deeper camera/software problems can be escalated or routed to manufacturer resources.')}${tabs([['Get Started','#/aac/eyegaze-duo/get-started'],['Positioning & Calibration','#/aac/eyegaze-duo/positioning'],['Help','#/aac/eyegaze-duo/help']])}<div class="grid three">${card('Get Started','Turn on, check USB, position the user, open eye gaze software and calibrate.','#/aac/eyegaze-duo/get-started')}${card('Positioning & Calibration','Use the 45–60 cm positioning guide and eye-level screen relationship.','#/aac/eyegaze-duo/positioning')}${card('Troubleshooting','Camera detection, tracking accuracy and calibration failures.','#/aac/eyegaze-duo/help')}</div>${relatedResources(['resource-eyegaze-au-product-sheet','resource-irisbond-kb','resource-eye-gaze-grid3'],'EyeGaze Duo resources')}</div>`}
function eyeStart(){return `<div class="page">${pageTitle([['AAC','#/aac'],['EyeGaze Duo','#/aac/eyegaze-duo'],['Get Started']], 'EyeGaze Duo — Get Started')}${steps([['Turn on the device','Press and hold the power button until the screen lights up.'],['Check cable connections','Confirm the USB-C camera connection and the USB-A connection to the device/hub.','aac-eyegaze-usb.jpg'],['Position the user','Start around 45–60 cm away and keep the top of the screen around eye level.','aac-eyegaze-positioning.jpg'],['Open eye gaze software','Open the configured EyeGaze / calibration software if it does not start automatically.'],['Calibrate','Complete calibration before opening communication software.'],['Open Grid 3 / communication software','After successful calibration, open the intended AAC software.']])}${relatedResources(['resource-eyegaze-au-product-sheet','resource-irisbond-kb','resource-grid3-support'],'Setup resources')}</div>`}
function eyePosition(){return `<div class="page">${pageTitle([['AAC','#/aac'],['EyeGaze Duo','#/aac/eyegaze-duo'],['Positioning']], 'Positioning & Calibration','Position before calibrating. Recalibration cannot compensate for an unstable or unsuitable physical setup.')}<div class="split"><div><section class="section"><h2>Positioning</h2><div class="grid two">${card('Distance','Start approximately 45–60 cm from the display.','#/aac/eyegaze-duo/positioning')}${card('Height','Keep the top of the screen approximately level with the user’s eyes.','#/aac/eyegaze-duo/positioning')}</div>${img('aac-eyegaze-positioning.jpg','EyeGaze positioning guide')}</section><section class="section"><h2>Calibration</h2><p class="lede">Centre the user’s eyes within the calibration/positioning feedback, confirm the camera can see the eyes, then choose the calibration point count appropriate to the software. More points generally trade time for precision.</p></section></div><aside class="sidebar">${mascot('nodi','If tracking is poor, correct the physical setup before repeatedly recalibrating.')}</aside></div></div>`}
function eyeHelp(){return `<div class="page">${pageTitle([['AAC','#/aac'],['EyeGaze Duo','#/aac/eyegaze-duo'],['Help']], 'EyeGaze Duo Troubleshooting')}<div class="grid two">${card('Camera not detected','Recheck USB-C at the camera and USB-A at the device/hub.','#/aac/eyegaze-duo/get-started')}${card('Tracking inaccurate','Return to positioning, eye visibility and calibration.','#/aac/eyegaze-duo/positioning')}</div><section class="section"><h2>Related EyeGaze FAQs</h2>${faqList('EyeGaze')}</section><section class="section"><h2>Manufacturer resources</h2><p class="lede">For deeper camera configuration, firmware or software-specific questions, use the curated IRISBOND / Smartbox resources in the Resource Library.</p>${relatedResources(['resource-irisbond-kb','resource-irisbond-tips-tricks','resource-eye-gaze-grid3','resource-windows-eye-control-troubleshoot'],'Manufacturer & software resources')}<a class="btn secondary" href="#/resources">Open full Resources →</a></section></div>`}
function trilogy(){return `<div class="page">${pageTitle([['AAC','#/aac'],['NeuroNode Trilogy']], 'NeuroNode Trilogy','Treat Trilogy as an orchestrator: hardware setup here, then link to the shared NeuroNode, EyeGaze and Grid 3 guides for deeper help.')}${tabs([['Windows','#/aac/trilogy/windows'],['iOS','#/aac/trilogy/ios'],['Using the device','#/aac/trilogy/using'],['Help & FAQs','#/aac/trilogy/help']])}<div class="grid four">${card('Get Started — Windows','What’s included → power → cables → EyeGaze → NeuroNode → Grid 3.','#/aac/trilogy/windows')}${card('Get Started — iOS','Power → toggle → Hiru → NeuroNode → Grid for iPad / AAC app.','#/aac/trilogy/ios')}${card('Using the device','NeuroNode switching, EyeGaze, charging, mounting and software.','#/aac/trilogy/using')}${card('Help & FAQs','Route the issue to the correct subsystem.','#/aac/trilogy/help')}</div>${relatedResources(['resource-trilogy-docs','resource-neuronode-user-guide-rev-m','resource-grid3-support'],'NeuroNode Trilogy resources')}</div>`}
function trilogyOS(os){const w=os==='windows';return `<div class="page os-page">${osSwitch(os,'#/aac/trilogy/windows','#/aac/trilogy/ios')}${pageTitle([['AAC','#/aac'],['Trilogy','#/aac/trilogy'],[w?'Windows':'iOS']],`NeuroNode Trilogy — ${w?'Windows':'iOS'} Setup`)}${steps(w?[['What’s included','Trilogy device, charger, wall charger and NeuroNode accessories.','nn-trilogy-windows-setup-1.jpg'],['Turn on the device','Press the power button and wait for the screen.'],['Check EyeGaze connections','Confirm all EyeGaze cables are secure.'],['Position and calibrate EyeGaze','Position the user before completing calibration.'],['Connect NeuroNode','Open Controller App, Shake to Wake and connect.','nn-trilogy-windows-setup-2.jpg'],['Place NeuroNode','Use the established electrode type and access site.'],['Open Grid 3','Open Grid 3 or the configured communication software and test communication.']]:[['What’s included','Trilogy/iOS device plus NeuroNode accessories.','nn-trilogy-ios-setup-1.jpg'],['Turn on the device','Press and hold the power button.'],['Check the rear toggle','Confirm the device toggle switch is on.'],['Set up EyeGaze with Hiru','Use the Hiru app and iOS Accessibility eye tracking settings as required.'],['Connect NeuroNode','Open Controller App, Shake to Wake and connect.','nn-trilogy-ios-setup-2.jpg'],['Place NeuroNode','Use the established access site.'],['Open Grid for iPad / AAC software','Test EyeGaze and NeuroNode access in the intended communication app.']])}${relatedResources(w?['resource-trilogy-docs','resource-grid3-support','resource-surface-drivers']:['resource-trilogy-docs','resource-hiru-ipad','resource-grid-ipad-support','resource-apple-assistivetouch'],'Resources for this version')}</div>`}
function trilogyUsing(){return `<div class="page">${pageTitle([['AAC','#/aac'],['Trilogy','#/aac/trilogy'],['Using the device']], 'Using NeuroNode Trilogy','Use shared guides instead of duplicating the same NeuroNode or EyeGaze content inside Trilogy.')}<div class="grid three">${card('NeuroNode switching','Placement, signal, switching and Controller App.','#/aac/neuronode')}${card('EyeGaze','Positioning, calibration and camera troubleshooting.','#/aac/eyegaze-duo')}${card('Grid 3','Configure NeuroNode as a switch input.','#/aac/neuronode/grid3')}${card('Charging','NeuroNode charging and device power checks.','#/aac/neuronode/get-started')}${card('Mounting','Device, table and floor positioning support.','#/aac/mounts')}${card('Resources','Manuals and manufacturer links.','#/resources')}</div></div>`}
function trilogyHelp(){return `<div class="page">${pageTitle([['AAC','#/aac'],['Trilogy','#/aac/trilogy'],['Help']], 'Trilogy Help & FAQs','First identify which subsystem is failing.')}<div class="grid four">${card('NeuroNode problem','Connection, signal, switching or reset.','#/aac/neuronode/help')}${card('EyeGaze problem','USB, positioning or calibration.','#/aac/eyegaze-duo/help')}${card('Grid 3 problem','Switch connection and key detection.','#/aac/neuronode/grid3')}${card('Trilogy hardware','Power, cables, device or mounting issue.','#/support')}</div><section class="section">${faqList('Trilogy')}</section></div>`}
function mounts(){return `<div class="page">${pageTitle([['AAC','#/aac'],['Mounting']], 'Mounting & Positioning','Mounting supports multiple AAC systems, so it sits alongside—not inside—the device list.')}<div class="grid three">${card('Table mounting','Short-term and trial table positioning.','#/aac/mounts')}${card('Floor stand','Flexible floor-based positioning for trials and demonstrations.','#/aac/mounts')}${card('Wheelchair / custom mounting','Use the correct approved mounting solution and seek support where configuration is unclear.','#/support')}</div><section class="section">${img('aac-mounts-1.jpg','Table stand')}${img('aac-mounts-2.jpg','Floor stand')}</section>${relatedResources(['resource-rehadapt-table','resource-rehadapt-floor','resource-rehadapt-main'],'Mounting resources')}<div class="callout warning"><strong>Safety:</strong> mounting instructions should follow the supplied mounting-system documentation and local safety practices. Escalate uncertain configurations to Support.</div></div>`}
function neurostrip(){return `<div class="page">${hero('NEUROSTRIP','Measure. Analyse. Learn.','Get started with NeuroStrip, learn the application workflow, troubleshoot signal issues or build EMG knowledge in the Academy.',`<a class="btn primary" href="#/neurostrip/get-started">Get Started →</a><a class="btn secondary" href="#/academy">EMG Academy →</a><a class="btn secondary" href="#/neurostrip/help">Help & FAQs →</a>`)}<section class="section"><div class="section-head"><h2>Using NeuroStrip for</h2></div><div class="grid three">${card('Rehabilitation','Operational pathway for rehab-oriented use.','#/neurostrip/rehabilitation')}${card('Sports & Performance','Operational pathway for performance and training workflows.','#/neurostrip/sport')}${card('Dysphagia','Supplied swallowing-related resource with clear clinical boundaries.','#/neurostrip/dysphagia')}</div></section><section class="section"><div class="grid three">${card('Placement & Signal','Skin prep, patch alignment and EMG placement.','#/neurostrip/placement')}${card('Protocols & Sessions','Create a protocol, start a session and use graph controls.','#/neurostrip/sessions')}${card('Data & Export','Review saved sessions, measurements and exports.','#/neurostrip/data')}</div></section><section class="section">${mascot('nero','The universal setup workflow is shared across rehabilitation, sports and dysphagia pathways. Application pages should not repeat charging, skin prep and connection instructions.')}</section></div>`}
function neuroGetStarted(){return `<div class="page">${pageTitle([['Home','#/'],['NeuroStrip','#/neurostrip'],['Get Started']], 'NeuroStrip Getting Started','A single end-to-end workflow. Use this as the flagship onboarding guide rather than scattering setup across application pages.')}<div class="progress" aria-label="Ten-step guide"><span style="width:100%"></span></div><div style="height:16px"></div>${steps([['Check what’s in the box','Typical supplied kit includes NeuroStrip devices, Power Management Pods, patches, Alignment Guide and wall charger.','ns-guide-overview.png'],['Charge NeuroStrip','Seat each device properly in the charging pod and confirm the pod indicator state.'],['Prepare the skin','Shave if required, clean/abrade as instructed and let the site dry completely.','ns-skin-preparation.jpg'],['Align the patch','Use the alignment base/tool so the NeuroStrip and patch are correctly joined before placement.','ns-patch-alignment.jpg'],['Place NeuroStrip','Position over the intended muscle and align with muscle fibre direction.','ns-emg-placement-1.jpg'],['Connect NeuroStrip','Wake, scan/discover, connect and assign the device to the correct channel/body placement.','ns-guide-connections.png'],['Create or select a client','Use Patient / Client Manager to select or create the person being recorded.','ns-guide-new-patient.png'],['Choose a protocol','Select an existing protocol or build a new protocol with channels, timing and repetitions.','ns-guide-protocols.png'],['Start the session','Confirm device/channel assignments and live signal, then record.','ns-guide-new-session.png'],['Review and export','Review sessions, measurements and available export actions.','ns-guide-measurements.png']])}</div>`}
function neuroPlacement(){return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],['Placement']], 'Skin Preparation, Patch Alignment & EMG Placement')}<div class="grid three">${card('1. Skin preparation','Prepare the site for reliable contact.','#/neurostrip/placement')}${card('2. Patch alignment','Join the patch and sensor correctly with the alignment tool.','#/neurostrip/placement')}${card('3. EMG placement','Place over the intended muscle and align with fibre direction.','#/neurostrip/placement')}</div><section class="section">${img(guideAssets.ns.skin,'NeuroStrip skin preparation')}${img(guideAssets.ns.patch,'NeuroStrip patch alignment')}${img(guideAssets.ns.placement1,'NeuroStrip EMG placement principles')}${img(guideAssets.ns.placement2,'NeuroStrip placement examples')}</section><div class="callout"><strong>Skin-prep principle:</strong> after cleaning / preparation, the skin should be completely dry before the patch is applied.</div></div>`}
function neuroSessions(){return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],['Protocols & Sessions']], 'Protocols & Sessions')}<section class="section"><h2>Create or edit a protocol</h2>${img(guideAssets.ns.protocols,'NeuroStrip protocols')}${img(guideAssets.ns.create1,'Create NeuroStrip protocol details')}${img(guideAssets.ns.create2,'Create NeuroStrip protocol timeline')}${img(guideAssets.ns.edit,'Edit NeuroStrip protocol')}</section><section class="section"><h2>Start a session</h2>${img(guideAssets.ns.newSession,'New NeuroStrip session')}${img(guideAssets.ns.selectProtocol,'Select NeuroStrip protocol')}${img(guideAssets.ns.sessionGraph,'NeuroStrip live session graph')}</section><section class="section"><h2>Session controls</h2>${img(guideAssets.ns.graphControls,'NeuroStrip graph controls')}</section></div>`}
function neuroData(){return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],['Data & Export']], 'Graphs, Measurements & Export','After collecting data, use this page to understand where to review sessions and where operational export actions live.')}<section class="section"><h2>Session graph</h2>${img(guideAssets.ns.sessionGraph,'NeuroStrip session graph')}${img(guideAssets.ns.graphControls,'NeuroStrip graph controls')}</section><section class="section"><h2>Saved sessions & measurements</h2>${img(guideAssets.ns.patientSessions,'NeuroStrip saved sessions')}${img(guideAssets.ns.measurements,'NeuroStrip measurements and trends')}</section><div class="callout"><strong>Want to understand the signal itself?</strong> The EMG Academy is the learning layer; this page remains operational product guidance. <a href="#/academy">Open EMG Academy →</a></div></div>`}
function neuroHelp(){return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],['Help']], 'NeuroStrip Troubleshooting & FAQs','Troubleshoot by symptom: connection, signal, patch, charging or app workflow.')}<div class="grid three">${card('Won’t connect','Wake, Bluetooth, Connections, scan/discover and channel assignment.','#/neurostrip/get-started')}${card('Signal is erratic / low','Skin preparation, adherence, alignment and placement.','#/neurostrip/placement')}${card('Need a reset','Hard reset with the reset pin, then reconnect in the app.','#/neurostrip/help')}</div><section class="section">${img(guideAssets.ns.troubleshooting,'NeuroStrip troubleshooting guide')}</section><section class="section"><h2>NeuroStrip FAQs</h2>${faqList('NeuroStrip')}</section></div>`}
function neuroPath(type){const isSport=type==='sport';return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],[isSport?'Sports & Performance':'Rehabilitation']], isSport?'Sports & Performance Pathway':'Rehabilitation Pathway','Application pathway built on top of the universal NeuroStrip setup rather than repeating it.')}<div class="grid three">${card('1. Start with universal setup','Charge, skin prep, patch alignment, placement and connection.','#/neurostrip/get-started')}${card('2. Choose the protocol','Select or create the workflow for the session.','#/neurostrip/sessions')}${card('3. Record and review','Run the session, review graphs/measurements and export as required.','#/neurostrip/data')}</div><section class="section">${mascot('nero',isSport?'Use the same signal-quality fundamentals across performance sessions. Avoid comparing amplitude blindly between different placements or people.':'Operational support can explain the product workflow, while clinical interpretation remains with the appropriate healthcare professional.')}</section></div>`}
function dysphagia(){return `<div class="page">${pageTitle([['NeuroStrip','#/neurostrip'],['Dysphagia']], 'Dysphagia','This section uses the supplied dysphagia resource. It is intentionally framed as product-operation and educational content, not diagnosis or treatment advice.')}<div class="callout warning"><strong>Clinical boundary:</strong> swallowing assessment and treatment require appropriately qualified clinical expertise and local governance.</div><section class="section">${img(guideAssets.ns.dysphagia1,'NeuroStrip dysphagia overview')}${img(guideAssets.ns.dysphagia2,'NeuroStrip dysphagia use cases')}</section></div>`}
function academy(){const courses=[...new Set(DATA.academy.map(x=>x.course))];return `<div class="page">${hero('NEUROSTRIP EMG ACADEMY','Learn surface EMG. One short lesson at a time.','Designed as the future home for approximately 15 five-minute training videos. Each lesson gets its own shareable page, written summary and related product guides.',`<a class="btn primary" href="#/academy/${DATA.academy[0].id}">Start learning →</a>`)}<section class="section"><div class="section-head"><div><h2>15 planned lessons</h2><p>Videos are placeholders until approved training media is uploaded through the future admin workflow.</p></div></div>${courses.map(c=>`<div class="faq-group"><h3>${c}</h3><div class="grid two">${DATA.academy.filter(x=>x.course===c).map((x,i)=>`<a class="card lesson-card" href="#/academy/${x.id}"><span class="lesson-index">${String(DATA.academy.indexOf(x)+1).padStart(2,'0')}</span><span style="flex:1"><strong>${e(x.title)}</strong><small style="display:block;color:var(--muted)">${e(x.summary)}</small></span><span class="badge">${x.duration}</span></a>`).join('')}</div></div>`).join('')}</section></div>`}
function lesson(id){const l=DATA.academy.find(x=>x.id===id);if(!l)return notFound();const i=DATA.academy.indexOf(l),prev=DATA.academy[i-1],next=DATA.academy[i+1];return `<div class="page">${pageTitle([['EMG Academy','#/academy'],[l.title]], l.title,`${l.course} • Lesson ${i+1} of ${DATA.academy.length} • ${l.duration}`)}<div class="video-placeholder"><div><div class="play">▶</div><strong>Training video placeholder</strong><div>This slot is ready for an uploaded/embedded ~5 minute lesson.</div></div></div><section class="section"><div class="grid two"><article class="card"><h3>What you’ll learn</h3><p>${e(l.summary)}</p></article><article class="card"><h3>Key takeaway</h3><p>Use this lesson to build EMG understanding; use the NeuroStrip support pages for operational setup and troubleshooting.</p></article></div></section><section class="section"><div class="hero-actions">${prev?`<a class="btn secondary" href="#/academy/${prev.id}">← ${e(prev.title)}</a>`:''}${next?`<a class="btn primary" href="#/academy/${next.id}">${e(next.title)} →</a>`:'<a class="btn primary" href="#/academy">Back to Academy</a>'}</div></section></div>`}
function faqs(){return `<div class="page">${pageTitle([['Home','#/'],['FAQs']], 'Troubleshooting & FAQs','Searchable, filterable answers across AAC and NeuroStrip. Repeated support cases should become FAQs here over time.')}<div class="filter-row" id="faqFilters">${['All','NeuroNode','EyeGaze','UNO Touch','Trilogy','NeuroStrip'].map((x,i)=>`<button class="chip ${i===0?'active':''}" data-faq-filter="${x}">${x}</button>`).join('')}</div><div id="faqContent">${faqList()}</div></div>`}
function resources(){const groups=[...new Set(DATA.resources.map(r=>r.provider||'Other'))];return `<div class="page page-wide">${pageTitle([['Home','#/'],['Resources']], 'Resource Library','A central library of manuals, product sheets, software, accessibility guidance and trusted external support. Relevant resources also appear contextually throughout the device guides.')}<div class="filter-row"><span class="chip active">All</span><span class="chip">Manuals</span><span class="chip">Product Sheets</span><span class="chip">Troubleshooting</span><span class="chip">Accessibility</span><span class="chip">Software</span><span class="chip">Useful Links</span></div>${groups.map(g=>`<section class="section resource-provider"><div class="section-head"><div><h2>${e(g)}</h2><p>${g==='Control Bionics'?'Official product, documentation and support links.':g==='Smartbox / Grid'?'Grid 3, Grid for iPad and Smartbox software support.':g==='IRISBOND / Hiru / Oskol 2'?'Eye gaze, Hiru and Oskol 2 documentation.':g==='Apple / iPad'?'Relevant iPad accessibility and support guidance.':g==='Microsoft / Windows / Surface'?'Windows, Surface and Eye Control support.':g==='Rehadapt / Mounting'?'Mounting systems and stand information.':'Additional resources.'}</p></div></div><div class="grid three">${DATA.resources.filter(r=>(r.provider||'Other')===g).map(resourceCard).join('')}</div></section>`).join('')}</div>`}

function support(){return `<div class="page">${pageTitle([['Home','#/'],['Support']], 'Contact Support','If self-service guidance does not resolve the issue, contact Control Bionics Support with enough information for efficient triage.')}<div class="grid three">${card('Email Support','Support.au@controlbionics.com','mailto:Support.au@controlbionics.com','Send email →')}${card('Call Support','1300 971 744','tel:1300971744','Call →')}${card('Book a support session','Use the organisation’s current Microsoft Bookings support link.','#/resources','Find booking link →')}</div><section class="section"><div class="card"><h3>Before contacting Support</h3><p>Have the device/product name, serial number if available, Windows/iOS device type, a clear description of the problem, what changed before the issue, and screenshots/photos where useful.</p></div></section></div>`}
function admin(){return `<div class="page">${pageTitle([['Home','#/'],['Admin']], 'Content Admin — prototype','A front-end prototype showing how future staff content management should work. Production publishing should use Supabase Auth + Storage + a metadata table; do not expose service-role/secret keys in the browser.')}<div class="admin-shell"><nav class="admin-nav"><strong>Content Manager</strong><a href="#/admin">Dashboard</a><a href="#/admin">Guides</a><a href="#/admin">FAQs</a><a href="#/admin">Academy</a><a href="#/admin">Resources</a></nav><section class="admin-panel"><div class="grid four">${['Guides','FAQs','Academy videos','Resources'].map((x,i)=>`<div class="card"><small class="muted">${x}</small><h2>${[28,DATA.faq.length,DATA.academy.length,DATA.resources.length][i]}</h2></div>`).join('')}</div><section class="section"><h2>Add / edit Academy lesson</h2><div class="field"><label>Title</label><input value="Understanding EMG Amplitude"></div><div class="grid two"><div class="field"><label>Course</label><select><option>EMG Fundamentals</option><option>Signal Quality</option><option>Electrode Placement</option></select></div><div class="field"><label>Duration</label><input value="05:00"></div></div><div class="field"><label>Video URL / storage path</label><input placeholder="Supabase Storage path or approved video URL"></div><div class="field"><label>Description</label><textarea rows="4">Explain the lesson and key learning objectives.</textarea></div><div class="hero-actions"><button class="btn primary" type="button" onclick="alert('Prototype only — connect Supabase before production publishing.')">Save draft</button><button class="btn secondary" type="button">Publish</button></div></section><section class="section"><div class="callout"><strong>Recommended production model:</strong> GitHub Pages frontend + Supabase Auth, Storage and Postgres metadata. Public visitors only read published content; approved staff authenticate to upload and edit.</div></section></section></div></div>`}
function notFound(){return `<div class="page">${pageTitle([['Home','#/'],['Not found']], 'Page not found')}<a class="btn primary" href="#/">Return home</a></div>`}
const routes={
'/':home,'/aac':aac,'/aac/uno-touch':uno,'/aac/uno-touch/windows':()=>unoSetup('windows'),'/aac/uno-touch/ios':()=>unoSetup('ios'),'/aac/uno-touch/help':()=>`<div class="page">${pageTitle([['AAC','#/aac'],['UNO Touch','#/aac/uno-touch'],['Help']], 'UNO Touch Help & FAQs')}${faqList('UNO Touch')}</div>`,
'/aac/neuronode':neuroNode,'/aac/neuronode/get-started':neuroNodeGetStarted,'/aac/neuronode/emg':neuroNodeEmg,'/aac/neuronode/signal':neuroNodeSignal,'/aac/neuronode/settings':neuroNodeSettings,'/aac/neuronode/grid3':neuroNodeGrid,'/aac/neuronode/help':neuroNodeHelp,
'/aac/neuronode-duo':duo,'/aac/neuronode-duo/windows':()=>duoOS('windows'),'/aac/neuronode-duo/ios':()=>duoOS('ios'),'/aac/eyegaze-duo':eye,'/aac/eyegaze-duo/get-started':eyeStart,'/aac/eyegaze-duo/positioning':eyePosition,'/aac/eyegaze-duo/help':eyeHelp,'/aac/trilogy':trilogy,'/aac/trilogy/windows':()=>trilogyOS('windows'),'/aac/trilogy/ios':()=>trilogyOS('ios'),'/aac/trilogy/using':trilogyUsing,'/aac/trilogy/help':trilogyHelp,'/aac/mounts':mounts,
'/neurostrip':neurostrip,'/neurostrip/get-started':neuroGetStarted,'/neurostrip/placement':neuroPlacement,'/neurostrip/sessions':neuroSessions,'/neurostrip/data':neuroData,'/neurostrip/help':neuroHelp,'/neurostrip/rehabilitation':()=>neuroPath('rehab'),'/neurostrip/sport':()=>neuroPath('sport'),'/neurostrip/dysphagia':dysphagia,'/academy':academy,'/faqs':faqs,'/resources':resources,'/support':support,'/admin':admin
};
function route(){const raw=location.hash.slice(1)||'/';const m=raw.match(/^\/academy\/([^/?#]+)/);app.innerHTML=m?lesson(m[1]):(routes[raw]?routes[raw]():notFound());window.scrollTo(0,0);bind();setActive(raw)}
function bind(){document.querySelectorAll('[data-zoom]').forEach(im=>im.onclick=()=>{const d=document.getElementById('imageDialog');document.getElementById('imageDialogImg').src=im.src;document.getElementById('imageDialogImg').alt=im.alt;document.getElementById('imageDialogLink').href=im.src;d.showModal()});document.querySelectorAll('[data-open-search]').forEach(b=>b.onclick=openSearch);document.querySelectorAll('[data-search-trigger]').forEach(i=>i.addEventListener('keydown',ev=>{if(ev.key==='Enter'){openSearch();document.getElementById('globalSearch').value=i.value;search(i.value)}}));document.querySelectorAll('[data-faq-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-faq-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('faqContent').innerHTML=faqList(b.dataset.faqFilter==='All'?null:b.dataset.faqFilter)})}
function setActive(path){document.querySelectorAll('.main-nav a').forEach(a=>{const p=a.getAttribute('href').slice(1);a.classList.toggle('active',p==='/'?path==='/':path.startsWith(p))})}
function openSearch(){document.getElementById('searchDialog').showModal();const i=document.getElementById('globalSearch');setTimeout(()=>i.focus(),30)}
function search(q){const box=document.getElementById('searchResults');const res=searchContent(DATA,q);if(!(q||'').trim()){box.innerHTML='<div class="empty">Type a product, symptom or task.</div>';return}box.innerHTML=res.length?res.map(r=>`<a class="search-result" href="${r.h}" ${r.h.startsWith('http')?'target="_blank" rel="noopener"':''}><strong>${e(r.t)}</strong><span>${e(r.s)}</span></a>`).join(''):'<div class="empty">No confident match. Try the product name plus the issue.</div>'}
document.getElementById('searchOpen').onclick=openSearch;document.getElementById('globalSearch').addEventListener('input',e=>search(e.target.value));document.getElementById('menuBtn').onclick=()=>document.getElementById('mainNav').classList.toggle('open');document.getElementById('mainNav').addEventListener('click',()=>document.getElementById('mainNav').classList.remove('open'));window.addEventListener('hashchange',route);route();
